// single-item input: Settings emits one config object and discovery takes one
// filter set. The dataset rejects any key it does not know, so only the four it
// accepts are sent - `location` is required and the rest may be blank.
const cfg = $input.first().json;
const location = String(cfg.location || '').trim();
if (!location) {
  throw new Error('Settings.location is required, for example "Austin, TX".');
}

return [{ json: { payload: [{
  location: location,
  listingCategory: String(cfg.listing_category || 'House for sale'),
  HomeType: String(cfg.home_type || ''),
  days_on_zillow: String(cfg.days_on_zillow || '7 days'),
}] } }];

// single-item input: the trigger endpoint answers once with one snapshot id.
const res = $input.first().json;

// Bright Data answers validation errors with HTTP 200 and an error body, and
// this node runs with neverError, so an unchecked response looks like a success
// and fails several nodes later blaming the wrong thing.
if (res.error || res.errors) {
  throw new Error('Bright Data rejected the search: ' + JSON.stringify(res.error || res.errors));
}
if (!res.snapshot_id) {
  throw new Error('No snapshot_id in the Bright Data response: ' + JSON.stringify(res).slice(0, 400));
}

return [{ json: { snapshot_id: res.snapshot_id } }];

// 30 polls at 60 seconds is half an hour, and that is deliberate headroom
// rather than caution. Two discovery runs on the same dataset, same filters and
// the same record cap, fifteen minutes apart: the first finished in 289
// seconds, the second was still running at 16 minutes. Sizing the cap to the
// fast run would have killed the slow one. Without any cap the IF below loops
// on itself all night, so it needs a number - just not an optimistic one.
const MAX_POLLS = 30;

// single-item input: the progress endpoint returns one status object.
const res = $input.first().json;
const snapshotId = $('Check Search Accepted').first().json.snapshot_id;
const attempt = $runIndex + 1;

if (res.error) {
  throw new Error('Progress check failed: ' + JSON.stringify(res.error));
}
if (res.status === 'failed') {
  throw new Error('Bright Data reported the snapshot failed: ' + JSON.stringify(res).slice(0, 400));
}
if (res.status !== 'ready' && attempt >= MAX_POLLS) {
  throw new Error(
    'Snapshot ' + snapshotId + ' still ' + res.status + ' after ' + attempt +
    ' polls. Raise MAX_POLLS or narrow the search in Settings.'
  );
}

return [{ json: {
  status: res.status,
  snapshot_id: snapshotId,
  attempt: attempt,
  records: res.records || 0,
} }];

// Discovery runs with include_errors=true, which is what makes a failed crawl
// visible instead of silently shrinking the result set. Those rows arrive with
// an error_code and no price, so left in they score as free houses.
const cfg = $('Settings').first().json;
const maxPrice = Number(cfg.max_price) || 0;
const minBeds = Number(cfg.min_beds) || 0;

const out = [];
const seen = {};
let failedRows = 0;

for (const item of $input.all()) {
  const j = item.json || {};
  if (j.error || j.error_code || j.warning) { failedRows += 1; continue; }

  const zpid = String(j.zpid || '');
  const price = Number(j.price) || 0;
  if (!zpid || seen[zpid] || !price) { continue; }
  seen[zpid] = true;

  if (maxPrice && price > maxPrice) continue;
  if (minBeds && (Number(j.bedrooms) || 0) < minBeds) continue;

  // `homeValuation` is an array holding ONE JSON string, and the top-level
  // `zestimate` came back null on every row measured. The comparable sales
  // inside that string are the only usable benchmark in the response.
  const comps = [];
  const raw = Array.isArray(j.homeValuation) ? j.homeValuation[0] : j.homeValuation;
  if (typeof raw === 'string' && raw.length > 2) {
    try {
      const parsed = JSON.parse(raw);
      const list = ((parsed || {}).comparables || {}).comps || [];
      for (const c of list) {
        const p = (c && c.property) || {};
        const value = Number(p.price) || Number(p.lastSoldPrice) || Number(p.zestimate) || 0;
        const area = Number(p.livingAreaValue) || 0;
        if (value > 0 && area > 0) comps.push(Math.round(value / area));
      }
    } catch (e) { /* a malformed blob just means no benchmark for this row */ }
  }

  const overview = j.overview || {};
  const sqft = Number(j.livingArea) || Number(j.livingAreaValue) || 0;

  out.push({ json: {
    zpid: zpid,
    address: String(j.streetAddress || (j.address && j.address.streetAddress) || ''),
    city: String(j.city || (j.address && j.address.city) || ''),
    state: String(j.state || (j.address && j.address.state) || ''),
    zipcode: String(j.zipcode || (j.address && j.address.zipcode) || ''),
    url: String(j.hdpUrl || j.url || ''),
    price: price,
    beds: Number(j.bedrooms) || 0,
    baths: Number(j.bathrooms) || 0,
    sqft: sqft,
    year_built: Number(j.yearBuilt) || 0,
    home_type: String(j.homeType || ''),
    home_status: String(j.homeStatus || ''),
    days_on_zillow: Number(j.daysOnZillow) || Number(overview.days_on_zillow) || 0,
    views: Number(overview.number_of_views) || 0,
    saves: Number(overview.number_of_saves) || 0,
    price_per_sqft: sqft ? Math.round(price / sqft) : 0,
    comp_prices_per_sqft: comps,
    price_history: Array.isArray(j.priceHistory) ? j.priceHistory : [],
  } });
}

// A step that can empty the branch takes every node below it with it, so a run
// that found nothing still emits one marker item and reaches the quiet branch
// through the IF rather than by disappearing.
if (!out.length) {
  return [{ json: { nothing_found: true, failed_rows: failedRows } }];
}
out[0].json.failed_rows = failedRows;
return out;

// Two ways a price falls, and only one of them leaves a "Price change" event.
//
// 1. A real change event. Its `priceChangeRate` is a fraction, so -0.0435 is a
//    4.35% cut.
// 2. A relist. One measured home was listed at $1,799,000 ten days after being
//    removed at $1,899,000, with no change event anywhere in its history. A
//    filter that only looks for change events misses that 5% cut completely.
//
// What the field cannot be trusted for is the size of the move on a fresh
// listing: `priceChangeRate` compares to whatever event came before, however
// old. One row carried 2.4058 on its listing event because the event before it
// was a 2023 rental at $8,500 a month.
const cfg = $('Settings').first().json;
const windowDays = Math.max(1, Number(cfg.cut_window_days) || 60);
const cutoff = Date.now() - windowDays * 86400000;

function asTime(e) {
  const t = Number(e.time) || 0;
  if (t) return t;
  const d = Date.parse(String(e.date || ''));
  return isNaN(d) ? 0 : d;
}

const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (j.nothing_found) { out.push({ json: j }); continue; }

  const events = (j.price_history || [])
    .map((e) => ({
      time: asTime(e),
      date: String(e.date || ''),
      event: String(e.event || ''),
      price: Number(e.price) || 0,
      rate: Number(e.priceChangeRate) || 0,
      rental: !!e.postingIsRental,
    }))
    .filter((e) => e.time)
    .sort((a, b) => b.time - a.time);

  let cutPct = 0;
  let cutFrom = 0;
  let cutOn = '';
  let cutKind = '';

  for (let i = 0; i < events.length; i++) {
    const e = events[i];
    if (e.time < cutoff) break;

    if (e.event === 'Price change' && e.rate < 0 && e.price) {
      cutPct = Math.round(Math.abs(e.rate) * 1000) / 10;
      cutFrom = e.rate !== -1 ? Math.round(e.price / (1 + e.rate)) : 0;
      cutOn = e.date;
      cutKind = 'price change';
      break;
    }

    // A relist only counts against another *listing* event. Comparing today's
    // asking price to an old sale or to a rental is where the 240% rise came
    // from, so sales and rentals are skipped rather than used as the baseline.
    if (e.event === 'Listed for sale' && e.price) {
      const prior = events.slice(i + 1).find((p) =>
        (p.event === 'Listing removed' || p.event === 'Listed for sale' ||
         p.event === 'Price change') && p.price > 0 && !p.rental);
      if (prior && prior.price > e.price && prior.time >= cutoff - windowDays * 86400000) {
        cutPct = Math.round(((prior.price - e.price) / prior.price) * 1000) / 10;
        cutFrom = prior.price;
        cutOn = e.date;
        cutKind = 'relisted lower';
        break;
      }
    }
  }

  out.push({ json: {
    ...j,
    price_history: undefined,
    listed_on: (events.find((e) => e.event === 'Listed for sale') || {}).date || '',
    cut_pct: cutPct,
    cut_from: cutFrom,
    cut_on: cutOn,
    cut_kind: cutKind,
    has_cut: cutPct > 0,
  } });
}

return out;

// The benchmark is the median of the comparable sales Zillow attached to each
// listing, pooled across the whole run. One listing's five comps are a thin
// sample; the pool from a market's worth of listings is a usable local rate.
const cfg = $('Settings').first().json;
const minDiscount = Number(cfg.min_discount_pct) || 0;
const maxListings = Math.max(1, Number(cfg.max_listings) || 8);

const rows = $input.all().map((x) => x.json).filter((r) => !r.nothing_found && r.zpid);
const failedRows = ($input.all()[0] || { json: {} }).json.failed_rows || 0;

function median(values) {
  const v = values.slice().sort((a, b) => a - b);
  if (!v.length) return 0;
  const mid = Math.floor(v.length / 2);
  return v.length % 2 ? v[mid] : Math.round((v[mid - 1] + v[mid]) / 2);
}

const pool = [];
for (const r of rows) pool.push(...(r.comp_prices_per_sqft || []));
const marketRate = median(pool);

const scored = [];
for (const r of rows) {
  const own = median(r.comp_prices_per_sqft || []);
  const benchmark = own || marketRate;
  const discount = (benchmark && r.price_per_sqft)
    ? Math.round(((benchmark - r.price_per_sqft) / benchmark) * 1000) / 10
    : 0;

  // Saves per hundred views. A cheap home nobody saves is cheap for a reason;
  // a cheap home being saved is a queue forming. Neither price nor days on
  // market can tell those apart, and both fields were filled on every row.
  const saveRate = r.views ? Math.round((r.saves / r.views) * 1000) / 10 : 0;

  scored.push({
    ...r,
    comp_prices_per_sqft: undefined,
    comps_used: (r.comp_prices_per_sqft || []).length,
    benchmark_per_sqft: benchmark,
    market_per_sqft: marketRate,
    discount_pct: discount,
    save_rate: saveRate,
    // Weighted so a cut and a genuine discount both count, with attention as
    // the tiebreak rather than the driver.
    score: Math.round(
      (discount * 2) + (Number(r.cut_pct) * 3) + (saveRate * 1.5) +
      Math.min(Number(r.days_on_zillow) || 0, 90) / 10
    ),
  });
}

// Either signal qualifies. A home can be well under the local rate without ever
// having been cut, and a 6% cut still matters on a home priced at the market.
const qualifying = scored
  .filter((r) => r.has_cut || r.discount_pct >= minDiscount)
  .sort((a, b) => b.score - a.score)
  .slice(0, maxListings);

if (!qualifying.length) {
  return [{ json: {
    nothing_found: true,
    listings_seen: rows.length,
    failed_rows: failedRows,
    market_per_sqft: marketRate,
  } }];
}

return qualifying.map((r) => ({ json: {
  ...r,
  listings_seen: rows.length,
  failed_rows: failedRows,
} }));

