// The Information Extractor REPLACES the item rather than merging into it -
// every row arrives as {output: {...}} and the address is gone by this point -
// so the join back is positional, on the order the extractor received.
const scored = $('Score The Listings').all().map((x) => x.json);
const items = $input.all();
const stamp = new Date().toISOString().slice(0, 10);

// The model ignores a schema's wording often enough to plan for, so the verdict
// is folded back to the three values the sheet is allowed to hold.
function normaliseVerdict(v) {
  const s = String(v || '').toLowerCase();
  if (s.indexOf('skip') !== -1 || s.indexOf('avoid') !== -1 || s.indexOf('pass') !== -1) return 'skip';
  if (s.indexOf('view') !== -1 || s.indexOf('strong') !== -1 || s.indexOf('act') !== -1) return 'worth a viewing';
  return 'watch it';
}

const rows = [];
for (let i = 0; i < items.length; i++) {
  const src = scored[i];
  if (!src || !src.zpid) continue;
  const j = items[i].json || {};
  const a = (j.output && typeof j.output === 'object') ? j.output : j;

  rows.push({
    found_on: stamp,
    address: src.address,
    city: src.city,
    zipcode: src.zipcode,
    price: src.price,
    beds: src.beds,
    baths: src.baths,
    sqft: src.sqft,
    price_per_sqft: src.price_per_sqft,
    benchmark_per_sqft: src.benchmark_per_sqft,
    discount_pct: src.discount_pct,
    cut_pct: src.cut_pct,
    cut_from: src.cut_from || '',
    cut_on: src.cut_on || '',
    cut_kind: src.cut_kind || '',
    days_on_zillow: src.days_on_zillow,
    views: src.views,
    saves: src.saves,
    save_rate: src.save_rate,
    score: src.score,
    verdict: normaliseVerdict(a.verdict),
    reason: String(a.reason || '').slice(0, 500),
    watch_out_for: String(a.watch_out_for || '').slice(0, 300),
    url: src.url,
  });
}

// A listing whose verdict failed still belongs in the sheet. A missing row
// reads as "this one was fine", which is the opposite of what happened.
for (const src of scored) {
  if (!src || !src.zpid) continue;
  if (rows.some((r) => r.address === src.address && r.price === src.price)) continue;
  rows.push({
    found_on: stamp,
    address: src.address,
    city: src.city,
    zipcode: src.zipcode,
    price: src.price,
    beds: src.beds,
    baths: src.baths,
    sqft: src.sqft,
    price_per_sqft: src.price_per_sqft,
    benchmark_per_sqft: src.benchmark_per_sqft,
    discount_pct: src.discount_pct,
    cut_pct: src.cut_pct,
    cut_from: src.cut_from || '',
    cut_on: src.cut_on || '',
    cut_kind: src.cut_kind || '',
    days_on_zillow: src.days_on_zillow,
    views: src.views,
    saves: src.saves,
    save_rate: src.save_rate,
    score: src.score,
    verdict: 'watch it',
    reason: 'no verdict was returned for this listing',
    watch_out_for: 'read it by hand',
    url: src.url,
  });
}

if (!rows.length) {
  return [{ json: { nothing_found: true } }];
}
return rows.map((r) => ({ json: r }));

// Reads the report by name rather than from this node's input, because the
// Sheets append in between returns its own confirmation shape.
const rows = $('Build Listing Report').all().map((x) => x.json).filter((r) => r.address);
const scored = $('Score The Listings').all().map((x) => x.json);
const cfg = $('Settings').first().json;

if (!rows.length) {
  return [{ json: { message: 'Zillow check ran and found nothing worth reporting.' } }];
}

// max_listings is a user setting, so "1 listings" is reachable on any tight
// filter. Pluralise the counts rather than only the ones that got noticed.
const plural = (n, word) => n + ' ' + word + (Number(n) === 1 ? '' : 's');
const seen = Number((scored[0] || {}).listings_seen || 0);
const failed = Number((scored[0] || {}).failed_rows || 0);
const rate = Number((scored[0] || {}).market_per_sqft || 0);

const lines = [
  '*' + cfg.location + '* - ' + plural(rows.length, 'listing') + ' worth a look out of ' +
    plural(seen, 'listing') + ' checked' +
    (rate ? ', local rate $' + rate + '/sqft' : ''),
  '',
];

for (const r of rows) {
  lines.push('*$' + r.price.toLocaleString('en-US') + '*  ' + r.address + ', ' + r.city +
    '  _' + r.verdict + '_');
  lines.push('   ' + r.beds + ' bed, ' + r.baths + ' bath, ' + r.sqft + ' sqft - $' +
    r.price_per_sqft + '/sqft against $' + r.benchmark_per_sqft +
    (r.discount_pct > 0 ? ' (' + r.discount_pct + '% under)' : ''));
  if (r.cut_pct) {
    lines.push('   Cut ' + r.cut_pct + '% on ' + r.cut_on + ' from $' +
      Number(r.cut_from).toLocaleString('en-US') + ' - ' + r.cut_kind);
  }
  lines.push('   ' + plural(r.days_on_zillow, 'day') + ' listed, ' + r.views + ' views, ' +
    r.saves + ' saves (' + r.save_rate + ' per 100)');
  lines.push('   ' + r.reason);
  lines.push('   _Check:_ ' + r.watch_out_for);
  lines.push('   ' + r.url);
  lines.push('');
}

if (failed) {
  lines.push(plural(failed, 'listing') + ' could not be crawled and ' +
    (failed === 1 ? 'was' : 'were') + ' left out.');
}
lines.push('Full detail in the sheet. Filters: ' + cfg.listing_category + ', listed within ' +
  cfg.days_on_zillow + (cfg.max_price ? ', under $' + cfg.max_price : '') + '.');

return [{ json: { message: lines.join('\n') } }];

// Optional. Splice between 'Build Listing Report' and 'Log Listings To Sheet'
// when the people reading the digest think in monthly payments rather than
// sticker price. A $60k cut is abstract; $380 a month is not. Rate and deposit
// are the two numbers worth changing.
const annualRate = 6.5;
const depositPct = 20;
const years = 30;
return items.map((item) => {
  const j = item.json || {};
  const price = Number(j.price) || 0;
  const borrowed = price * (1 - depositPct / 100);
  const r = annualRate / 100 / 12;
  const months = years * 12;
  const payment = (r > 0 && borrowed > 0)
    ? borrowed * r / (1 - Math.pow(1 + r, -months))
    : 0;
  return { json: { ...j,
    deposit: Math.round(price * depositPct / 100),
    monthly_payment: Math.round(payment),
  } };
});
